// MT2009_PLUS_MIKSTURY_V1 (rule): one bonus (affect type + point) of a potion, a juice, a water, a dew, an elixir or an
// ItemShop buff (server-patches/mikstury/README.md; the owner, 4 November 2026). Nothing of that type and point on:
// yes. A stronger one on: no ("Silniejszy efekt..."). The same value on and lasting at least as long as the new one
// would: no - the item would be spent for nothing. Otherwise yes: the caller adds with override + per point, so the
// new value and time replace the old (a refresh, or an upgrade). Different points / types never meet here.
bool MiksturyMayRefresh(LPCHARACTER ch, DWORD dwType, WORD wPoint, long lValue, long lDuration)
{
	if (!ch)
		return false;
	const CAffect* pkAff = ch->FindAffect(dwType, wPoint);
	if (!pkAff)
		return true;
	if (pkAff->lApplyValue > lValue)
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "Silniejszy efekt tego rodzaju ju\277 dzia\263a.");
		return false;
	}
	if (pkAff->lApplyValue == lValue && pkAff->lDuration >= lDuration)
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "Ten efekt ju\277 dzia\263a i potrwa d\263u\277ej ni\277 nowy.");
		return false;
	}
	return true;
}

